function slider(label,key,min,max,step=1,suffix=''){const v=String(key==='exposure'?0:(DEFAULTS[key]??0));return `<div class="nx-photo-field"><span>${label}</span><input type="range" min="${min}" max="${max}" step="${step}" value="${v}" data-photo-range="${key}"><output>${v}${suffix}</output></div>`}
function aiPrompt(mode){const g={auto:'balanced flagship photo enhancement with natural contrast, recovered highlights, open shadows, accurate color and crisp detail',relight:'natural professional relighting only; improve exposure, highlights and shadows without changing identity or scene',color:'accurate white balance and premium color correction without oversaturation',portrait:'natural portrait polish; protect skin texture and identity, use gentle light/color/detail adjustments only',denoise:'reduce visible noise while keeping edges and natural texture',detail:'recover crisp photographic detail without halos or oversharpening'};return `Analyze this image for ${g[mode]||g.auto}. Return ONLY valid JSON with numeric keys exposure(-1..1), brightness(-20..20), contrast(-30..30), highlights(-50..50), shadows(-50..50), whites(-30..30), blacks(-30..30), temperature(-30..30), tint(-30..30), vibrance(-30..40), saturation(-25..25), clarity(-20..30), dehaze(-10..25), sharpness(0..45), noiseReduction(0..45), vignette(0..20), fade(0..15). No markdown.`}

